```

Then two files that each implement it:

```typescript
// lib/payments/StripeProvider.ts
export class StripeProvider implements PaymentProvider {
  async createIntent({ amountCents, currency, metadata }) {
    return stripe.paymentIntents.create({
      amount: amountCents, currency, metadata
    });
  }
  // ...
}

// lib/payments/XenditProvider.ts
export class XenditProvider implements PaymentProvider {
  async createIntent({ amountCents, currency, metadata }) {
    return Xendit.PaymentRequest.createPaymentRequest({
      amount: amountCents / 100,
      currency: 'IDR',
      referenceId: metadata.restaurant_id,
      metadata
    });
  }
  // ...
}
```

