```typescript
// lib/payments/index.ts
export function getPaymentProvider(): PaymentProvider {
  const provider = process.env.PAYMENT_PROVIDER; // 'stripe' | 'xendit'
  if (provider === 'xendit') return new XenditProvider();
  return new StripeProvider(); // default
}
```

Every API route just calls `getPaymentProvider().createIntent(...)` — it never knows or cares which one runs underneath.

