```swift
@Observable
class BaseAgent: AgentProtocol {
    let id = UUID()
    let role: AgentRole
    var workspace: Workspace
    var memory: AgentMemory
    var isActive = false

    func execute(task: Task) async -> TaskResult {
        isActive = true
        defer { isActive = false }
        do {
            let plan   = try await plan(goal: task.goal)
            let result = try await executePlan(plan)
            let ref    = try await reflect(on: result)
            memory.store(ref)
            return result
        } catch {
            return TaskResult.failure(error)
        }
    }
}
