final class PhotosLibraryService {
    func fetchAllImages() -> [PHAsset] {
        let opts = PHFetchOptions()
        opts.sortDescriptors = [NSSortDescriptor(key: "creationDate", ascending: false)]
        let res = PHAsset.fetchAssets(with: .image, options: opts)

        var assets: [PHAsset] = []
        assets.reserveCapacity(res.count)
        res.enumerateObjects { a, _, _ in assets.append(a) }
        return assets
    }

