  permissions: string[] | null | undefined,
  area: Area
): boolean {
  if (!role) return false;
  if ((RUOLI_ESCLUSI as readonly string[]).includes(role)) return false;
  if (role === RUOLO_SUPERADMIN) return true;
  return Array.isArray(permissions) && permissions.includes(area);
}

