export async function requireStaff(area: Area) {
  const cookieStore = await cookies();
  const supabase = createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    { cookies: { getAll: () => cookieStore.getAll(), setAll: () => {} } }
  );

  const { data: { user } } = await supabase.auth.getUser();
  if (!user) throw new Error("Non autenticato");

  const { data: profile } = await supabase
    .from("profiles")
    .select("role, permissions, status")
    .eq("id", user.id)
    .single();

  if (!profile) throw new Error("FORBIDDEN: profilo assente.");
  if (profile.status !== "active") throw new Error("FORBIDDEN: utenza sospesa.");

  if (!puoAccedere(profile.role, profile.permissions, area)) {
    throw new Error(`FORBIDDEN: nessun accesso all'area ${area}.`);
  }

  return { userId: user.id, role: profile.role, permissions: profile.permissions ?? [] };
}

