```swift
func handleDeleteKey() {
    guard let item = selectedItem, !item.isFolder else { return }

    if rememberDeleteChoice && !confirmDelete {
        // Elimina direttamente senza conferma
        Task {
            _ = await deleteFile(item)
        }
