Unlike Stripe (which confirms payment client-side via Elements), Xendit payments are confirmed asynchronously (guest scans QR in their own app). The frontend needs to poll for completion:

client-side via Elements), Xendit payments are confirmed asynchronously (guest scans QR in their own app). The frontend needs to poll for completion:

```typescript
// After creating a Xendit payment, poll for status
const pollPaymentStatus = async (paymentReference: string) => {
  const interval = setInterval(async () => {
    const res = await fetch(`/api/public/pay/status/${paymentReference}`);
    const data = await res.json();
    if (data.status === 'succeeded') {
      clearInterval(interval);
      showSuccessScreen();
    } else if (data.status === 'failed' || data.status === 'expired') {
      clearInterval(interval);
      showFailureScreen();
    }
  }, 3000);  // Poll every 3 seconds

  // Timeout after 5 minutes
  setTimeout(() => clearInterval(interval), 300000);
};
