// lib/currency.ts

const CURRENCY_CONFIG: Record<string, { symbol: string; position: 'before' | 'after'; decimals: number; separator: string }> = {
  HKD: { symbol: 'HK$', position: 'before', decimals: 2, separator: '.' },
  IDR: { symbol: 'Rp', position: 'before', decimals: 0, separator: '.' },
};

export function formatCurrency(amountInSmallestUnit: number, currency: string): string {
  const config = CURRENCY_CONFIG[currency] || CURRENCY_CONFIG.HKD;
  const amount = amountInSmallestUnit / Math.pow(10, config.decimals);

  if (config.decimals === 0) {
    // IDR: Rp 25.000
    return `${config.symbol} ${amount.toLocaleString('id-ID')}`;
  }
  // HKD: HK$5.00
  return `${config.symbol}${amount.toFixed(config.decimals)}`;
}
