// Create Xendit sub-account for new Indonesian restaurant
const createXenditSubAccount = async (restaurant: Restaurant) => {
  const response = await fetch('https://api.xendit.co/v2/accounts', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Basic ${Buffer.from(process.env.XENDIT_SECRET_KEY + ':').toString('base64')}`,
    },
    body: JSON.stringify({
      email: restaurant.owner_email,
      type: 'MANAGED',
      public_profile: {
        business_name: restaurant.name,
      },
    }),
  });

  const subAccount = await response.json();

  // Store the sub-account ID on the restaurant record
  await db.restaurants.update({
    where: { id: restaurant.id },
    data: { xendit_business_id: subAccount.id },
  });
};
