  'blurry', 'distorted geometry', 'warped walls', 'floating objects',
  'inconsistent shadows', 'unrealistic proportions', 'cartoon',
  'illustration', 'painting', 'sketch', 'watermark', 'text overlay',
  'fish-eye distortion', 'oversaturated colors', 'HDR tonemapping artifacts',
