unction computeProposedScores(
  proposedRooms: ProposalRoom[],
  wallOperations: WallOperation[],
  floorPlan: AnalyzedFloorPlan
): FloorPlanScores {

  const flow = computeFlowScore(proposedRooms, wallOperations, floorPlan);
  const light = computeLightScore(proposedRooms);
  const zoning = computeZoningScore(proposedRooms);
  const efficiency = computeEfficiencyScore(proposedRooms, floorPlan.total_area_sqm);
  const overall = Math.round(flow * 0.3 + light * 0.25 + zoning * 0.25 + efficiency * 0.2);

  return { flow, light, zoning, efficiency, overall };
}

function computeFlowScore(
  rooms: ProposalRoom[],
  wallOps: WallOperation[],
  floorPlan: AnalyzedFloorPlan
): number {
  // Circulation quality: penalise dead corridors, reward short paths between common rooms
  const corridors = rooms.filter(r => r.type === 'hallway');
  const totalCorridorArea = corridors.reduce((s, r) => s + r.area_sqm, 0);
  const totalArea = rooms.filter(r => r.status !== 'removed').reduce((s, r) => s + r.area_sqm, 0);

