  const totalArea = rooms.filter(r => r.status !== 'removed').reduce((s, r) => s + r.area_sqm, 0);

  // Corridor as % of total area — ideally 8–15%
  const corridorRatio = totalCorridorArea / totalArea;
  const corridorScore = corridorRatio < 0.08 ? 60   // too little — cramped
    : corridorRatio < 0.15 ? 90   // ideal
    : corridorRatio < 0.20 ? 75   // slightly over
    : 55;                           // too much wasted corridor

  // Accessibility bonus: all rooms accessible
  const accessibilityScore = rooms.every(r => r.is_accessible || r.status === 'removed') ? 100 : 50;

  return Math.round((corridorScore + accessibilityScore) / 2);
}

function computeLightScore(rooms: ProposalRoom[]): number {
  const habitable = rooms.filter(r =>
    ['bedroom', 'living_room', 'kitchen', 'dining_room', 'study'].includes(r.type) &&
    r.status !== 'removed'
