}

function computeZoningScore(rooms: ProposalRoom[]): number {
  // Public zone: living_room, kitchen, dining_room
  // Private zone: bedroom, bathroom, study
  // Ideal: private rooms are not directly accessible from public rooms without a hallway buffer
  const publicRooms = rooms.filter(r =>
    ['living_room', 'kitchen', 'dining_room'].includes(r.type) && r.status !== 'removed'
  );
  const privateRooms = rooms.filter(r =>
