}

function computeEfficiencyScore(rooms: ProposalRoom[], originalTotalArea: number): number {
  const activeRooms = rooms.filter(r => r.status !== 'removed');
  const corridors = activeRooms.filter(r => r.type === 'hallway');
  const usable = activeRooms.filter(r => r.type !== 'hallway');

  const corridorArea = corridors.reduce((s, r) => s + r.area_sqm, 0);
  const usableArea = usable.reduce((s, r) => s + r.area_sqm, 0);

  const efficiencyRatio = usableArea / (usableArea + corridorArea);
  // Ideal efficiency ratio: 85–92%
