function resolveConflicts(
  subRequests: SubRequest[],
  spaceResults: SpaceAllocationResult[],
  intent: ModificationIntent
): { satisfied: SubRequest[]; unsatisfied: SubRequest[]; conflict_note: string | null } {

  // Sort by priority_order
