tisfied: SubRequest[]; conflict_note: string | null } {

  // Sort by priority_order
  const ordered = intent.priority_order.map(i => subRequests[i]);

  // Greedily satisfy in priority order — first-come-first-served on space
  const satisfied: SubRequest[] = [];
  const unsatisfied: SubRequest[] = [];
  const usedZones = new Set<string>();

  for (const req of ordered) {
    const spaceResult = spaceResults[subRequests.indexOf(req)];
    if (spaceResult.source !== 'extension_required' &&
        !usedZones.has(spaceResult.source_room_id ?? '')) {
      satisfied.push(req);
      if (spaceResult.source_room_id) usedZones.add(spaceResult.source_room_id);
    } else {
      unsatisfied.push(req);
    }
  }

  return {
    satisfied,
    unsatisfied,
    conflict_note: unsatisfied.length > 0
      ? `Could not satisfy: ${unsatisfied.map(r => `${r.type} ${r.target_room_type}`).join(', ')} due to insufficient space. Satisfied ${satisfied.length} of ${ordered.length} requests.`
      : null
  };
}
