export async function withRetry<T>(
  operation: () => Promise<T>,
  options: RetryOptions = {}
): Promise<T> {
  const {
    maxRetries = 3,
    initialDelay = 2000,
    maxDelay = 10000,
    onRetry
  } = options;

  let lastError: any;

  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      return await operation();
    } catch (error: any) {
      lastError = error;

      const errorMessage = error?.message || String(error);
      const isQuotaError = errorMessage.includes("429") || errorMessage.toLowerCase().includes("quota exceeded");
      const isServerError = errorMessage.includes("500") || errorMessage.includes("503") || errorMessage.toLowerCase().includes("internal error");
      const isTokenLimitError = errorMessage.toLowerCase().includes("token limit") || errorMessage.toLowerCase().

e().includes("internal error");
      const isTokenLimitError = errorMessage.toLowerCase().includes("token limit") || errorMessage.toLowerCase().

includes("too many tokens");

      // If it's not a retryable error or we've reached max retries, throw
      if (!(isQuotaError || isServerError) || attempt === maxRetries) {
        // Enhance error message for token limit
        if (isTokenLimitError) {
          error.message = "The request is too large for the AI to process. Please try with a smaller file or less complex instructions.";
        } else if (isQuotaError) {
          error.message = "AI service is currently busy (Quota Exceeded). Please wait a moment and try again.";
        }
        throw error;
      }

      // Calculate delay with exponential backoff
      const delay = Math.min(initialDelay * Math.pow(2, attempt), maxDelay);

      if (onRetry) {
        onRetry(error, attempt + 1, delay);
      } else {
        console.warn(`API Error (Attempt ${attempt + 1}/${maxRetries + 1}): ${errorMessage}. Retrying in ${delay}ms...

t + 1, delay);
