```swift
@propertyWrapper
struct LossyArray<Element: Decodable>: Decodable {
    var wrappedValue: [Element]
    private struct Skip: Decodable {}   // consuma uno slot malformato

    init(from decoder: Decoder) throws {
        var container = try decoder.unkeyedContainer()
        var out: [Element] = []
        while !container.isAtEnd {
            do { out.append(try container.decode(Element.self)) }
            catch { _ = try? container.decode(Skip.self) }   // salta e prosegue
        }
        wrappedValue = out
    }
}
