// BlackHole
// Actor-isolated rate limiter for API calls

import Foundation

/// Thread-safe rate limiter using Swift actor isolation.
/// Ensures API calls respect provider rate limits with exponential backoff.
actor RateLimiter {

    // MARK: - Properties

    private var lastCallTime: Date = .distantPast
    private let minimumInterval: TimeInterval
    private var consecutiveWaits: Int = 0
    private let maxBackoffSeconds: TimeInterval = 60

    // MARK: - Init

    /// Create a rate limiter with calls per minute.
    init(callsPerMinute: Int) {
        self.minimumInterval = 60.0 / Double(max(callsPerMinute, 1))
    }

    /// Create a rate limiter with calls per second.
    init(callsPerSecond: Int) {
        self.minimumInterval = 1.0 / Double(max(callsPerSecond, 1))
    }

    // MARK: - Wait

    /// Wait if needed to respect the rate limit.

self.minimumInterval = 1.0 / Double(max(callsPerSecond, 1))
    }

    // MARK: - Wait

    /// Wait if needed to respect the rate limit.


    /// Uses exponential backoff after consecutive waits.
    func waitIfNeeded() async {
        let now = Date()
        let elapsed = now.timeIntervalSince(lastCallTime)

        if elapsed < minimumInterval {
            let waitTime = minimumInterval - elapsed
            let backoff = min(waitTime * pow(1.5, Double(consecutiveWaits)), maxBackoffSeconds)
            consecutiveWaits += 1

            try? await Task.sleep(nanoseconds: UInt64(backoff * 1_000_000_000))
        } else {
            consecutiveWaits = 0
        }

        lastCallTime = Date()
    }

    /// Handle an explicit rate limit response from the API.
    func handleRateLimit(retryAfter: TimeInterval) async {
        try? await Task.sleep(nanoseconds: UInt64(retryAfter * 1_000_000_000))
        lastCallTime = Date()
        consecutiveWaits = 0
    }

    /// Reset the rate limiter state.
    func reset() {
        lastCallTime = .distantPast
        consecutiveWaits = 0
    }
}
